              className="rounded-lg p-2"
              style={{ background: colors.surface }}
            >
              <div className="text-[11px] uppercase"
                    style={{ color: colors.muted }}>
                Skipped
              </div>
              <div className="text-xl font-bold"
                    style={{ color: colors.onSurface }}>
                {report.skipped_count}
